def magic_square_test(matrix):
    # Calculate the sum of the first row
    sum_first_row = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != sum_first_row:
            return False

    # Check if all columns have the same sum
    for i in range(len(matrix)):
        column_sum = sum(matrix[j][i] for j in range(len(matrix)))
        if column_sum != sum_first_row:
            return False

    # Check if the main diagonal has the same sum
    main_diagonal_sum = sum(matrix[i][i] for i in range(len(matrix)))
    if main_diagonal_sum != sum_first_row:
        return False

    # Check if the secondary diagonal has the same sum
    secondary_diagonal_sum = sum(matrix[i][len(matrix) - 1 - i] for i in range(len(matrix)))
    if secondary_diagonal_sum != sum_first_row:
        return False

    return True

