def max_sum(arr):
    n = len(arr)
    # Initialize the dp arrays for increasing and decreasing subsequences
    inc = [1] * n
    dec = [1] * n

    # Fill the dp arrays for increasing subsequences
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    # Fill the dp arrays for decreasing subsequences
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # Calculate the maximum sum of bitonic subsequences
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - 1)

    return max_sum

