def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Loop until we find the kth element
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            k -= 1
            i += 1
        else:
            k -= 1
            j += 1

    # If i is out of bounds, return the element from arr2
    if i == len(arr1):
        return arr2[j + k - 1]
    # If j is out of bounds, return the element from arr1
    elif j == len(arr2):
        return arr1[i + k - 1]
    # If k is 1, return the smaller element
    elif k == 1:
        return min(arr1[i], arr2[j])
    # If k is greater than 1, return the kth element from the remaining array
    else:
        if i < len(arr1):
            return find_kth(arr1[i + 1:], arr2, k - 1)
        else:
            return find_kth(arr1, arr2[j + 1:], k - 1)

