      arr = []
      return []

      If the array has any strange number ignore it:
      arr = [1, -1 , 55] 
            -> sort arr -> [-1, 1, 55]
            -> reverse arr -> [55, 1, -1]
      return = ['One']
    """

    def to_word(x: int) -> str:
        if x == 1:
            return 'One'
        elif x == 2:
            return 'Two'
        elif x == 3:
            return 'Three'
        elif x == 4:
            return 'Four'
        elif x == 5:
            return 'Five'
        elif x == 6:
            return 'Six'
        elif x == 7:
            return 'Seven'
        elif x == 8:
            return 'Eight'
        elif x == 9:
            return 'Nine'
        else:
            return ''

