def magic_square_test(my_matrix):
    s = sum(my_matrix[0])
    if any((sum(row) != s for row in my_matrix)):
        return False
    if sum((my_matrix[i][i] for i in range(len(my_matrix)))) != s:
        return False
    if sum((my_matrix[i][len(my_matrix) - i - 1] for i in range(len(my_matrix)))) != s:
        return False
    # Check the sum of the secondary diagonal
    secondary_diagonal_sum = sum(my_matrix[i][len(my_matrix) - i - 1] for i in range(len(my_matrix)))
    if secondary_diagonal_sum != s:
        return False
    return True

