    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        if a[i] >= a[0]:
            dp[0][i] = a[i] + a[0]
        else:
            dp[0][i] = a[i]
    for i in range(1, n):
        for j in range(n):
            if a[j] > a[i] and j > i:
                if dp[i - 1][i] + a[j] > dp[i - 1][j]:
                    dp[i][j] = dp[i - 1][i] + a[j]
                else:
                    dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]
    # Check if kth element is greater than the last element of the subsequence ending at index
    if k > index and dp[index][n - 1] < a[k]:
        return dp[index][n - 1] + a[k]
    return dp[index][k]

