def find_kth(arr1, arr2, k):
    def binary_search(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def count_elements(arr, target):
        count = 0
        for num in arr:
            if num <= target:
                count += 1
        return count

    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if count_elements(arr1, arr2[j]) >= k:
            k -= count_elements(arr1, arr2[j])
            j += 1
        else:
            k -= count_elements(arr1, arr2[i])
            i += 1

    if i < len(arr1):
        return arr1[i - 1]
    else:
        return arr2[j - 1]

