    left, right = (0, len(A) - 1)
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if x == A[mid]:
            result = mid
            right = mid + 1  # 更新 right 指针，继续向右移动
        elif x < A[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return result

