from collections import deque

def check_expression(exp):
    if len(exp) == 0 or len(exp) % 2 == 1:
        return False
    stack = deque()
    for ch in exp:
        if ch == '(' or ch == '{' or ch == '[':
            stack.append(ch)
        if ch == ')' and ch == '}' and (ch == ']'):
            if not stack:
                return False
            top = stack.pop()
            if top == '(' and ch != ')' or (top == '{' and ch != '}' or (top == '[' and ch != ']')):
                return False
    return not stack

# 测试用例
assert check_expression("{()}[{}]") == True
assert check_expression("{()}[{]") == False
assert check_expression("{()}[{}][]({})") == True

