    if len(lst) <= 1:
        return True
    count = {}
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
        if lst[i] in count:
            count[lst[i]] += 1
            if count[lst[i]] > 1:
