def prod_signs(arr):
    if not arr:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            product_of_signs *= -1
        sum_of_magnitudes += abs(num)

    return sum_of_magnitudes * product_of_signs

from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_path = [float('inf')] * k

    def dfs(x, y, path):
        nonlocal min_path
        if len(path) == k:
            if path < min_path:
                min_path = path.copy()
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, path + [grid[nx][ny]])

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])

    return min_path

