def is_sublist(l, s):
    # Check if the sublist is empty or the main list is empty
    if not s:
        return True
    if len(s) > len(l):
        return False
    # Iterate through the main list to find the starting index of the sublist
    for i in range(len(l)):
        if l[i] == s[0]:
            n = 1
            # Check if the elements after the starting index match the sublist
            while (n < len(s)) and (l[i+n] == s[n]):
                n += 1
            # If all elements match, return True
            if n == len(s):
                return True
    # If no match is found, return False
    return False

