def eulerian_num(n, m):
    # Base case: If m is greater than or equal to n, or n is 0, return 0
    if m >= n or n == 0:
        return 0
    # Base case: If m is 0, return 1
    if m == 0:
        return 1
    # Recursive relation to calculate Eulerian number
    return ((n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m))

