def amicable_numbers_sum(upper_limit):
    # Helper function to calculate the sum of proper divisors of a number
    def sum_of_divisors(n):
        return sum([i for i in range(1, n) if n % i == 0])

    # Initialize a list to store amicable numbers
    amicable_numbers = []

    # Iterate through numbers from 1 to the upper limit
    for num in range(1, upper_limit + 1):
        # Calculate the sum of divisors of the current number
        sum_div = sum_of_divisors(num)

        # Check if the sum of divisors is within the range and forms an amicable pair
        if sum_div > num and sum_of_divisors(sum_div) == num:
            amicable_numbers.append(num)
            amicable_numbers.append(sum_div)

    # Return the sum of all unique amicable numbers
    return sum(set(amicable_numbers))

# Test cases
