def is_majority(arr, n, x):
    # Find the first occurrence of x in arr
    i = 0
    while i < n:
        if arr[i] == x:
            break
        i += 1

    # If x is not present in arr, return False
    if i == n:
        return False

    # Check if x is the majority element
    if (i + n // 2) < n and arr[i + n // 2] == x:
        return True
    else:
        return False

