def get_total_number_of_sequences(m, n):
    # Initialize a 2D list to store the number of sequences
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Iterate over each possible maximum value for the sequence
    for i in range(1, m + 1):
        # Iterate over each possible length of the sequence
        for j in range(1, n + 1):
            # If the sequence length is 1, there is only one sequence for each value
            if j == 1:
                dp[i][j] = i
            else:
                # Calculate the number of sequences by summing up the possibilities
                dp[i][j] = dp[i - 1][j] + dp[i // 2][j - 1]

    # Return the total number of sequences of length n with maximum value m
    return dp[m][n]

def max_sum(arr):
    n = len(arr)
    # Initialize the list to store the maximum sum of increasing subsequence
    inc = [0] * n
    # Initialize the list to store the maximum sum of decreasing subsequence
    dec = [0] * n

    # Fill inc[] such that inc[i] contains the maximum sum of increasing subsequence
    # ending with arr[i]
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill dec[] such that dec[i] contains the maximum sum of decreasing subsequence
    # starting with arr[i]
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

def lps(s):
    n = len(s)
    # Create a 2D array to store the length of the longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    for cl in range(2, n + 1):  # cl is the length of the substring
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # The length of the longest palindromic subsequence is in dp[0][n-1]
    return dp[0][n - 1]

