def count_binary_seq(n):
    # Initialize a 2D list to store the binomial coefficients
    binomial = [[0 for x in range(n + 1)] for x in range(n + 1)]

    # Calculate binomial coefficients using the formula
    for i in range(n + 1):
        for j in range(min(i, n) + 1):
            if j == 0 or j == i:
                binomial[i][j] = 1
            else:
                binomial[i][j] = binomial[i - 1][j - 1] + binomial[i - 1][j]

    # Initialize a variable to store the result
    result = 0

    # Calculate the sum of binomial coefficients for each possible count of 1s
    for i in range(n + 1):
        result += binomial[n][i] * binomial[n][i]

    return result

