def find_lucas(n):
    # Base case: the first Lucas number is 2
    if n == 0:
        return 2
    # Base case: the second Lucas number is 1
    elif n == 1:
        return 1
    else:
        # Recursive call to find the sum of the two preceding Lucas numbers
        return find_lucas(n - 1) + find_lucas(n - 2)

