    # Base case: the first Catalan number is 1
    if n <= 1: 
        return 1

    # Initialize result
    res = 0

    # Calculate the nth Catalan number using the formula
    for i in range(n): 
        res += catalan_number(i) * catalan_number(n-i-1) 

    return res

