def max_sum_increasing_subseq(a, n, index, k):
    # Initialize the DP table with zeros
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the DP table
    for i in range(n):
        for j in range(n):
            if a[j] > a[i] and j > i:
                if dp[i - 1][i] + a[j] > dp[i - 1][j]:
                    dp[i][j] = dp[i - 1][i] + a[j]
                else:
                    dp[i][j] = dp[i - 1][j]
            else:
